export function parseCsvLine(line) {
  const fields = [];
  let i = 0;
  while (i < line.length) {
    if (line[i] === '"') {
      let field = '';
      i++; // skip opening quote
      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            i++; // skip closing quote
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }
      fields.push(field);
      if (i < line.length && line[i] === ',') {
        i++;
      }
    } else {
      const commaIndex = line.indexOf(',', i);
      if (commaIndex === -1) {
        fields.push(line.slice(i));
        break;
      } else {
        fields.push(line.slice(i, commaIndex));
        i = commaIndex + 1;
      }
    }
  }
  // Handle trailing comma -> empty field
  if (line.endsWith(',')) {
    fields.push('');
  }
  return fields;
}

